  1→<!DOCTYPE html>
  2→<html lang="en">
  3→<head>
  4→  <meta charset="UTF-8" />
  5→  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  6→  <title>Safecast Radiation Assistant</title>
  7→  <link rel="icon" type="image/png" href="safecast-square-ct.png" />
  8→  <style>
  9→    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
 10→
 11→    :root {
 12→      --bg:       #1a1e24;
 13→      --surface:  #242930;
 14→      --border:   #2e3540;
 15→      --blue:     #1e88e5;
 16→      --blue-dk:  #1565c0;
 17→      --green:    #1e88e5;
 18→      --green-dk: #1565c0;
 19→      --text:     #e4e8ef;
 20→      --muted:    #7a8494;
 21→      --user-bg:  #1e88e522;
 22→      --err:      #e17055;
 23→    }
 24→
 25→    html, body {
 26→      height: 100%;
 27→      background: var(--bg);
 28→      color: var(--text);
 29→      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
 30→      font-size: 15px;
 31→      line-height: 1.6;
 32→    }
 33→
 34→    /* ── Layout ── */
 35→    #app {
 36→      display: flex;
 37→      flex-direction: column;
 38→      height: 100%;
 39→      width: 90%;
 40→      max-width: 1200px;
 41→      margin: 0 auto;
 42→    }
 43→
 44→    header {
 45→      padding: 16px 20px 14px;
 46→      border-bottom: 1px solid var(--border);
 47→      display: flex;
 48→      align-items: center;
 49→      gap: 10px;
 50→      flex-shrink: 0;
 51→    }
 52→    header .logo {
 53→      width: 32px; height: 32px;
 54→      border-radius: 8px;
 55→      display: flex; align-items: center; justify-content: center;
 56→      overflow: hidden;
 57→      cursor: pointer;
 58→    }
 59→    header .logo img {
 60→      width: 100%; height: 100%;
 61→      object-fit: contain;
 62→    }
 63→    header .title-area { flex: 1; cursor: pointer; }
 64→    header .title-area:hover h1 { color: var(--green); }
 65→    header h1 { font-size: 16px; font-weight: 600; transition: color .15s; }
 66→    header p  { font-size: 12px; color: var(--muted); }
 67→
 68→    /* Download button in header */
 69→    #download-btn {
 70→      background: var(--green);
 71→      border: none;
 72→      border-radius: 8px;
 73→      padding: 6px 12px;
 74→      font-size: 13px;
 75→      cursor: pointer;
 76→      color: #fff;
 77→      display: flex;
 78→      align-items: center;
 79→      gap: 6px;
 80→      transition: background .15s;
 81→    }
 82→    #download-btn:hover { background: var(--green-dk); }
 83→    #download-btn svg { width: 14px; height: 14px; fill: #fff; }
 84→
 85→    /* ── Messages ── */
 86→    #messages {
 87→      flex: 1;
 88→      overflow-y: auto;
 89→      padding: 20px;
 90→      display: flex;
 91→      flex-direction: column;
 92→      gap: 16px;
 93→    }
 94→
 95→    .msg {
 96→      display: flex;
 97→      gap: 10px;
 98→      max-width: 100%;
 99→      position: relative;
100→    }
101→    .msg.user  { flex-direction: row-reverse; }
102→    .msg.user  .bubble { background: var(--user-bg); border: 1px solid var(--green); margin-left: 40px; }
103→    .msg.bot   .bubble { background: var(--surface); border: 1px solid var(--border); margin-right: 40px; position: relative; }
104→
105→    /* Copy button for bot messages */
106→    .msg.bot .copy-btn {
107→      position: absolute;
108→      top: 8px;
109→      right: 8px;
110→      background: var(--surface);
111→      border: 1px solid var(--border);
112→      border-radius: 6px;
113→      padding: 4px 8px;
114→      font-size: 11px;
115→      cursor: pointer;
116→      color: var(--muted);
117→      opacity: 0;
118→      transition: opacity .15s, color .15s, border-color .15s;
119→    }
120→    .msg.bot:hover .copy-btn { opacity: 1; }
121→    .msg.bot .copy-btn:hover { color: var(--green); border-color: var(--green); }
122→    .msg.bot .copy-btn.copied { color: var(--green); opacity: 1; }
123→
124→    .avatar {
125→      width: 30px; height: 30px; border-radius: 50%;
126→      flex-shrink: 0; display: flex; align-items: center; justify-content: center;
127→      font-size: 14px;
128→      overflow: hidden;
129→    }
130→    .msg.user .avatar { background: var(--green); color: #fff; }
131→    .msg.bot  .avatar { background: var(--surface); border: 1px solid var(--border); }
132→    .msg.bot  .avatar img { width: 100%; height: 100%; object-fit: contain; }
133→
134→    .bubble {
135→      padding: 10px 14px;
136→      border-radius: 12px;
137→      white-space: pre-wrap;
138→      word-break: break-word;
139→      line-height: 1.55;
140→    }
141→    .bubble strong { font-weight: 600; }
142→    .bubble em { font-style: italic; }
143→    .bubble code {
144→      background: rgba(255, 255, 255, 0.1);
145→      padding: 2px 6px;
146→      border-radius: 4px;
147→      font-family: 'SF Mono', Monaco, 'Cascadia Code', monospace;
148→      font-size: 13px;
149→    }
150→    .bubble a {
151→      color: var(--blue);
152→      text-decoration: none;
153→      border-bottom: 1px solid transparent;
154→      transition: border-color .15s;
155→    }
156→    .bubble a:hover { border-bottom-color: var(--blue); }
157→
158→    /* Markdown headers */
159→    .bubble h1 { font-size: 20px; font-weight: 700; margin: 16px 0 10px; color: var(--text); }
160→    .bubble h2 { font-size: 18px; font-weight: 600; margin: 14px 0 8px; color: var(--text); }
161→    .bubble h3 { font-size: 16px; font-weight: 600; margin: 12px 0 6px; color: var(--text); }
162→    .bubble h1 + br, .bubble h2 + br, .bubble h3 + br { display: none; } /* Remove line breaks after headers */
163→
164→    /* Markdown tables */
165→    .bubble table {
