328→<script>
329→  const messagesEl = document.getElementById('messages');
330→  const introEl    = document.getElementById('intro');
331→  const formEl     = document.getElementById('form');
332→  const msgEl      = document.getElementById('msg');
333→  const sendBtn    = document.getElementById('send');
334→
335→  let busy = false;
336→  let conversationHistory = []; // Track conversation for context
337→
338→  // Auto-grow textarea
339→  msgEl.addEventListener('input', () => {
340→    msgEl.style.height = 'auto';
341→    msgEl.style.height = Math.min(msgEl.scrollHeight, 120) + 'px';
342→  });
343→
344→  // Send on Enter (Shift+Enter = newline)
345→  msgEl.addEventListener('keydown', e => {
346→    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); submit(); }
347→  });
348→
349→  formEl.addEventListener('submit', submit);
350→
351→  function ask(chip) {
352→    msgEl.value = chip.textContent;
353→    submit();
354→  }
355→
356→  function submit() {
357→    const text = msgEl.value.trim();
358→    if (!text || busy) return;
359→    sendMessage(text);
360→    msgEl.value = '';
361→    msgEl.style.height = 'auto';
362→  }
363→
364→  // Convert markdown to HTML
365→  function markdownToHTML(text) {
366→    let html = text;
367→
368→    // Headers (must be at start of line)
369→    html = html.replace(/^### (.+)$/gm, '<h3>$1</h3>');
370→    html = html.replace(/^## (.+)$/gm, '<h2>$1</h2>');
371→    html = html.replace(/^# (.+)$/gm, '<h1>$1</h1>');
372→
373→    // Horizontal rules
374→    html = html.replace(/^---+$/gm, '<hr>');
375→
376→    // Tables (simple approach - detect table rows)
377→    html = html.replace(/^\|(.+)\|$/gm, function(match, content) {
378→      const cells = content.split('|').map(c => c.trim());
379→      const cellTags = cells.map(c => {
380→        // Check if this is a separator row (--|---|---)
381→        if (/^:?-+:?$/.test(c)) return null;
382→        return `<td>${c}</td>`;
383→      }).filter(Boolean);
384→      if (cellTags.length === 0) return '';
385→      return '<tr>' + cellTags.join('') + '</tr>';
386→    });
387→    // Wrap table rows in table tags
388→    html = html.replace(/(<tr>.+<\/tr>\n?)+/g, '<table>$&</table>');
389→
390→    // Unordered lists (lines starting with - or *)
391→    html = html.replace(/^[*-] (.+)$/gm, '<li>$1</li>');
392→    html = html.replace(/(<li>.+<\/li>\n?)+/g, '<ul>$&</ul>');
393→
394→    // Ordered lists (lines starting with 1., 2., etc)
395→    html = html.replace(/^\d+\. (.+)$/gm, '<li>$1</li>');
396→
397→    // Bold: **text** or __text__
398→    html = html.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
399→    html = html.replace(/__(.+?)__/g, '<strong>$1</strong>');
400→
401→    // Italic: *text* or _text_
402→    html = html.replace(/\*(.+?)\*/g, '<em>$1</em>');
403→    html = html.replace(/_(.+?)_/g, '<em>$1</em>');
404→
405→    // Inline code: `code`
406→    html = html.replace(/`(.+?)`/g, '<code>$1</code>');
407→
408→    // Links: [text](url) - do this BEFORE auto-linking plain URLs
409→    html = html.replace(/\[(.+?)\]\((.+?)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>');
410→
411→    // Auto-link plain URLs (but not ones already in <a> tags)
412→    html = html.replace(/(^|[^"'>])(https?:\/\/[^\s<]+)/g, function(match, prefix, url) {
413→      // Don't link if it's already inside an href attribute
414→      return prefix + '<a href="' + url + '" target="_blank" rel="noopener">' + url + '</a>';
415→    });
416→
417→    // Line breaks: preserve newlines, but not after block elements or between table rows
418→    html = html.replace(/\n/g, (match, offset, string) => {
419→      // Don't add <br> after closing block tags
420→      const beforeContext = string.substring(Math.max(0, offset - 50), offset);
421→      if (/<\/(table|ul|h[123]|tr)>\s*$/.test(beforeContext)) return '';
422→      // Don't add <br> before opening table rows
423→      const afterContext = string.substring(offset + 1, Math.min(string.length, offset + 10));
424→      if (/^\s*<tr>/.test(afterContext)) return '';
425→      return '<br>';
426→    });
427→
428→    return html;
429→  }
430→
431→  function addMessage(role, text, cls) {
432→    if (introEl) introEl.style.display = 'none';
433→
434→    const msg    = document.createElement('div');
435→    msg.className = `msg ${role}`;
436→
437→    const avatar = document.createElement('div');
438→    avatar.className = 'avatar';
439→    if (role === 'user') {
440→      avatar.textContent = '👤';
441→    } else {
442→      const img = document.createElement('img');
443→      img.src = 'safecast-square-ct.png';
444→      img.alt = 'Safecast';
445→      avatar.appendChild(img);
446→    }
447→
448→    const bubble = document.createElement('div');
449→    bubble.className = `bubble ${cls || ''}`;
450→    // User messages are plain text, bot messages support markdown
451→    if (role === 'bot') {
452→      bubble.innerHTML = markdownToHTML(text);
453→
454→      // Add copy button for bot messages
455→      const copyBtn = document.createElement('button');
456→      copyBtn.className = 'copy-btn';
457→      copyBtn.textContent = 'Copy';
458→      copyBtn.onclick = () => copyMessage(text, copyBtn);
459→      bubble.appendChild(copyBtn);
460→    } else {
461→      bubble.textContent = text;
462→    }
463→
464→    msg.appendChild(avatar);
465→    msg.appendChild(bubble);
466→    messagesEl.appendChild(msg);
467→    messagesEl.scrollTop = messagesEl.scrollHeight;
468→    return bubble;
469→  }
470→
471→  function copyMessage(text, btn) {
472→    navigator.clipboard.writeText(text).then(() => {
473→      const originalText = btn.textContent;
474→      btn.textContent = 'Copied!';
475→      btn.classList.add('copied');
476→      setTimeout(() => {
477→        btn.textContent = originalText;
478→        btn.classList.remove('copied');
479→      }, 2000);
480→    }).catch(err => {
481→      console.error('Failed to copy:', err);
482→    });
483→  }
484→
485→  function downloadConversation() {
486→    if (conversationHistory.length === 0) {
487→      alert('No conversation to download yet!');
488→      return;
489→    }
490→
491→    // Build markdown format
492→    let markdown = '# Safecast Radiation Assistant Conversation\n\n';
493→    markdown += `Date: ${new Date().toLocaleString()}\n\n`;
494→    markdown += '---\n\n';
495→
496→    conversationHistory.forEach(msg => {
497→      const role = msg.role === 'user' ? 'You' : 'Assistant';
498→      markdown += `## ${role}\n\n`;
499→      markdown += msg.content + '\n\n';
500→      markdown += '---\n\n';
501→    });
502→
503→    // Create download link
504→    const blob = new Blob([markdown], { type: 'text/markdown' });
505→    const url = URL.createObjectURL(blob);
506→    const a = document.createElement('a');
507→    a.href = url;
508→    a.download = `safecast-conversation-${new Date().toISOString().slice(0,10)}.md`;
509→    document.body.appendChild(a);
510→    a.click();
511→    document.body.removeChild(a);
512→    URL.revokeObjectURL(url);
513→  }
514→
515→  function clearConversation() {
516→    // Clear conversation history
517→    conversationHistory = [];
518→
519→    // Clear all messages
520→    while (messagesEl.firstChild) {
521→      messagesEl.removeChild(messagesEl.firstChild);
522→    }
523→
524→    // Show intro again
525→    messagesEl.appendChild(introEl);
526→    introEl.style.display = 'block';
527→
528→    // Focus on input
529→    msgEl.focus();
530→  }
531→
532→  function sendMessage(text) {
533→    busy = true;
534→    sendBtn.disabled = true;
535→
536→    addMessage('user', text);
537→    const botBubble = addMessage('bot', '…thinking…', 'thinking');
538→
539→    let accumulated = '';
540→
541→    function finish(success = true) {
542→      botBubble.classList.remove('thinking');
543→      busy = false;
544→      sendBtn.disabled = false;
545→      msgEl.focus();
546→
547→      // Add AI disclaimer to successful bot messages
548→      if (success && accumulated) {
549→        // Re-render with disclaimer
550→        const disclaimerText = '\n\n---\n\n_Note: AI-generated response using data from the Safecast radiation monitoring network. For critical safety decisions, please consult official sources._';
551→        botBubble.innerHTML = markdownToHTML(accumulated + disclaimerText);
552→
553→        // Re-add copy button (since we replaced innerHTML)
554→        const copyBtn = document.createElement('button');
555→        copyBtn.className = 'copy-btn';
556→        copyBtn.textContent = 'Copy';
557→        copyBtn.onclick = () => copyMessage(accumulated, copyBtn); // Copy without disclaimer
558→        botBubble.appendChild(copyBtn);
559→
560→        conversationHistory.push(
561→          { role: 'user', content: text },
562→          { role: 'assistant', content: accumulated }
563→        );
564→
565→        // Keep only last 10 messages (5 exchanges) to prevent rate limits
566→        const MAX_HISTORY = 10;
567→        if (conversationHistory.length > MAX_HISTORY) {
568→          conversationHistory = conversationHistory.slice(-MAX_HISTORY);
569→        }
570→      }
571→    }
572→
573→    fetch('/chat', {
574→      method: 'POST',
575→      headers: { 'Content-Type': 'application/json' },
576→      body: JSON.stringify({
577→        message: text,
578→        history: conversationHistory
579→      }),
580→    }).then(response => {
581→      const reader  = response.body.getReader();
582→      const decoder = new TextDecoder();
583→      let   buffer  = '';
584→
585→      function pump() {
586→        return reader.read().then(({ done, value }) => {
587→          if (done) { finish(); return; }
588→
589→          buffer += decoder.decode(value, { stream: true });
590→          const lines = buffer.split('\n');
591→          buffer = lines.pop(); // keep incomplete last line
592→
593→          for (const line of lines) {
594→            if (!line.trim()) continue;
595→            try {
596→              const ev = JSON.parse(line);
597→              if (ev.type === 'text') {
598→                if (botBubble.classList.contains('thinking')) {
599→                  botBubble.classList.remove('thinking');
600→                  accumulated = '';
601→                }
602→                accumulated += ev.text;
603→                botBubble.innerHTML = markdownToHTML(accumulated);
604→                messagesEl.scrollTop = messagesEl.scrollHeight;
605→              } else if (ev.type === 'done') {
606→                finish();
607→              } else if (ev.type === 'error') {
608→                botBubble.classList.remove('thinking');
609→                botBubble.classList.add('error');
610→                botBubble.textContent = 'Error: ' + ev.error;
611→                finish(false);
612→              }
613→            } catch { /* malformed line, skip */ }
614→          }
615→          return pump();
616→        });
617→      }
618→      return pump();
619→    }).catch(err => {
620→      botBubble.classList.remove('thinking');
621→      botBubble.classList.add('error');
622→      botBubble.textContent = 'Connection error: ' + err.message;
623→      finish(false);
624→    });
625→  }
626→
627→  msgEl.focus();
628→</script>
629→</body>
630→</html>
