369→    function initColumnResize() {
370→      const table = document.getElementById('usersTable');
371→      if (!table) return;
372→      const headerRow = table.querySelector('thead tr:first-child');
373→      if (!headerRow) return;
374→      const ths = headerRow.querySelectorAll('th');
375→
376→      ths.forEach((th, i) => {
