378→          th.style.width = columnWidths[i];
379→        } else {
380→          th.style.width = th.offsetWidth + 'px';
381→        }
382→      });
383→
384→      document.querySelectorAll('.resize-handle').forEach(handle => {
385→        handle.addEventListener('mousedown', function(e) {
386→          e.preventDefault();
387→          e.stopPropagation();
388→          resizing = true;
389→          const th = this.parentElement;
390→          const colIndex = Array.from(th.parentElement.children).indexOf(th);
391→          const startX = e.pageX;
392→          const startWidth = th.offsetWidth;
393→          this.classList.add('active');
394→
395→          const onMouseMove = (e) => {
396→            const newWidth = Math.max(40, startWidth + (e.pageX - startX));
397→            th.style.width = newWidth + 'px';
398→            columnWidths[colIndex] = newWidth + 'px';
399→          };
400→          const onMouseUp = () => {
401→            this.classList.remove('active');
402→            document.removeEventListener('mousemove', onMouseMove);
403→            document.removeEventListener('mouseup', onMouseUp);
404→            setTimeout(() => { resizing = false; }, 50);
405→          };
406→          document.addEventListener('mousemove', onMouseMove);
407→          document.addEventListener('mouseup', onMouseUp);
408→        });
409→      });
410→    }
