546→    function renderPaginationControls(controls, totalPages) {
547→      controls.innerHTML = '';
548→
549→      // First/Previous buttons
550→      const firstBtn = document.createElement('button');
551→      firstBtn.className = 'pagination-btn';
552→      firstBtn.textContent = 'First';
553→      firstBtn.disabled = currentPage === 1;
