560→      prevBtn.disabled = currentPage === 1;
561→      prevBtn.onclick = () => goToPage(currentPage - 1);
562→      controls.appendChild(prevBtn);
563→
564→      // Page numbers
565→      const startPage = Math.max(1, currentPage - 2);
566→      const endPage = Math.min(totalPages, currentPage + 2);
567→
568→      if (startPage > 1) {
569→        const ellipsis = document.createElement('span');
570→        ellipsis.textContent = '...';
571→        ellipsis.style.padding = '0 5px';
572→        controls.appendChild(ellipsis);
573→      }
574→
575→      for (let i = startPage; i <= endPage; i++) {
576→        const pageBtn = document.createElement('button');
577→        pageBtn.className = 'pagination-btn' + (i === currentPage ? ' active' : '');
578→        pageBtn.textContent = i;
579→        pageBtn.onclick = () => goToPage(i);
580→        controls.appendChild(pageBtn);
581→      }
582→
583→      if (endPage < totalPages) {
584→        const ellipsis = document.createElement('span');
585→        ellipsis.textContent = '...';
586→        ellipsis.style.padding = '0 5px';
587→        controls.appendChild(ellipsis);
588→      }
589→
590→      // Next/Last buttons
591→      const nextBtn = document.createElement('button');
592→      nextBtn.className = 'pagination-btn';
593→      nextBtn.textContent = 'Next';
594→      nextBtn.disabled = currentPage === totalPages || totalPages === 0;
595→      nextBtn.onclick = () => goToPage(currentPage + 1);
596→      controls.appendChild(nextBtn);
597→
598→      const lastBtn = document.createElement('button');
599→      lastBtn.className = 'pagination-btn';
600→      lastBtn.textContent = 'Last';
601→      lastBtn.disabled = currentPage === totalPages || totalPages === 0;
602→      lastBtn.onclick = () => goToPage(totalPages);
603→      controls.appendChild(lastBtn);
604→
605→      // Page info
606→      const pageInfo = document.createElement('span');
607→      pageInfo.style.marginLeft = '15px';
608→      pageInfo.style.color = 'var(--text-secondary)';
609→      const startItem = (currentPage - 1) * pageSize + 1;
610→      const endItem = Math.min(currentPage * pageSize, totalUsers);
611→      pageInfo.textContent = `${startItem}-${endItem} of ${totalUsers}`;
612→      controls.appendChild(pageInfo);
613→    }
