645→    // Sorting functionality (client-side for current page)
646→    let sortDirection = {};
647→    function sortTable(columnIndex) {
648→      if (resizing) return;
649→      const table = document.getElementById('usersTable');
650→      const tbody = document.getElementById('usersTableBody');
651→      const rows = Array.from(tbody.querySelectorAll('tr'));
652→      const header = table.querySelector('thead tr:first-child th:nth-child(' + (columnIndex + 1) + ')');
653→      const dataType = header.getAttribute('data-type');
654→
655→      const currentDir = sortDirection[columnIndex] || 'none';
656→      sortDirection[columnIndex] = currentDir === 'asc' ? 'desc' : 'asc';
657→
658→      table.querySelectorAll('.sortable').forEach(h => h.classList.remove('asc', 'desc'));
659→      header.classList.add(sortDirection[columnIndex]);
660→
661→      rows.sort((a, b) => {
662→        let aVal = a.cells[columnIndex].textContent.trim();
663→        let bVal = b.cells[columnIndex].textContent.trim();
664→
665→        if (dataType === 'number') {
666→          aVal = parseInt(aVal) || 0;
667→          bVal = parseInt(bVal) || 0;
668→          return sortDirection[columnIndex] === 'asc' ? aVal - bVal : bVal - aVal;
669→        }
670→
671→        if (dataType === 'date') {
672→          if (aVal === 'Never') aVal = new Date(0).toISOString();
673→          if (bVal === 'Never') bVal = new Date(0).toISOString();
674→          aVal = new Date(aVal).getTime();
675→          bVal = new Date(bVal).getTime();
676→          return sortDirection[columnIndex] === 'asc' ? aVal - bVal : bVal - aVal;
677→        }
678→
679→        if (sortDirection[columnIndex] === 'asc') {
680→          return aVal.localeCompare(bVal);
681→        } else {
682→          return bVal.localeCompare(aVal);
683→        }
684→      });
685→
686→      rows.forEach(row => tbody.appendChild(row));
687→    }
