751→      if (selected.length === 0) return;
752→      if (!confirm(`Delete ${selected.length} selected user(s)? This cannot be undone.`)) return;
753→
754→      const ids = selected.map(cb => cb.value);
755→      let errors = [];
756→      for (const id of ids) {
757→        try {
758→          const response = await fetch(addPasswordParam(`/api/admin/users/${id}`), {
759→            method: 'DELETE'
760→          });
761→          if (!response.ok) {
762→            const error = await response.json();
763→            errors.push(error.error || `Failed to delete user ${id}`);
764→          }
765→        } catch (err) {
766→          errors.push(`Network error for user ${id}`);
767→        }
768→      }
769→      if (errors.length > 0) {
