272→async function fetchData() {
273→  const loading = document.getElementById('loading');
274→  const table = document.getElementById('dataTable');
275→  const noData = document.getElementById('noData');
276→
277→  loading.style.display = 'block';
278→  table.style.display = 'none';
279→  noData.style.display = 'none';
280→
281→  let url = `/api/admin/mcp/data?table=${currentTable}&limit=${currentLimit}&offset=${currentOffset}&sort=${currentSort}&order=${currentOrder}`;
282→  if (PASSWORD) url += '&password=' + encodeURIComponent(PASSWORD);
283→  if (currentSearch) url += '&search=' + encodeURIComponent(currentSearch);
284→
285→  try {
286→    const resp = await fetch(url);
287→    if (!resp.ok) {
288→      if (resp.status === 401) {
289→        loading.textContent = 'Unauthorized - please login as admin or provide password';
290→        return;
291→      }
292→      // Try to parse error JSON
293→      try {
294→        const errJson = await resp.json();
295→        if (errJson.error) {
296→          loading.textContent = errJson.error;
297→          return;
298→        }
299→      } catch {}
300→      if (resp.status === 503) {
301→        loading.textContent = 'DuckDB analytics not available. Ensure DUCKLAKE_PG_URL is configured and ducklake_catalog database exists.';
302→        return;
303→      }
304→      throw new Error('HTTP ' + resp.status);
305→    }
306→
307→    const json = await resp.json();
308→    totalRows = json.total;
309→    const columns = json.columns || [];
