331→      const sortClass = currentSort === col ? (currentOrder === 'asc' ? 'sortable asc' : 'sortable desc') : 'sortable';
332→      headerHTML += `<th class="${sortClass}" onclick="sortBy('${col}')">${label}<span class="resize-handle"></span></th>`;
333→    });
334→    headerHTML += '</tr>';
335→    // Filter row
336→    headerHTML += '<tr class="filter-row"><th></th>';
337→    columns.forEach(col => {
338→      const label = COLUMN_LABELS[col] || col;
339→      headerHTML += `<th><input type="text" class="filter-input" placeholder="${label}..." onkeyup="filterTable()"></th>`;
340→    });
341→    headerHTML += '</tr>';
342→    thead.innerHTML = headerHTML;
343→
344→    // Build body
345→    const tbody = document.getElementById('tableBody');
346→    let bodyHTML = '';
347→    data.forEach((row, idx) => {
348→      const keyVal = row[keyCol];
349→      bodyHTML += `<tr><td class="checkbox-col"><input type="checkbox" class="row-cb" value="${keyVal}" onchange="updateDeleteBtn()"></td>`;
350→      columns.forEach(col => {
351→        let val = row[col];
352→        if (val === null || val === undefined) val = '';
353→        const strVal = String(val);
354→        if (EXPANDABLE.has(col) && strVal.length > 60) {
355→          const preview = strVal.substring(0, 60) + '...';
356→          bodyHTML += `<td class="expandable" title="Click to expand" onclick="showModal('${COLUMN_LABELS[col] || col}', ${JSON.stringify(strVal).replace(/'/g, "&#39;")})">${escapeHtml(preview)}</td>`;
357→        } else if (col === 'is_mobile' || col === 'cloudfront') {
358→          bodyHTML += `<td>${val ? 'Yes' : (val === false ? 'No' : '')}</td>`;
359→        } else if (col === 'timestamp' || col === 'client_timestamp') {
360→          bodyHTML += `<td>${formatTimestamp(strVal)}</td>`;
361→        } else {
362→          bodyHTML += `<td>${escapeHtml(strVal)}</td>`;
363→        }
364→      });
365→      bodyHTML += '</tr>';
366→    });
367→    tbody.innerHTML = bodyHTML;
368→    table.style.display = 'table';
369→    initColumnResize();
370→    updateDeleteBtn();
371→
372→    // Summary
373→    const page = Math.floor(currentOffset / currentLimit) + 1;
374→    const totalPages = Math.ceil(totalRows / currentLimit);
375→    document.getElementById('summary').textContent = `${totalRows} total rows | Page ${page} of ${totalPages}`;
376→
377→    // Pagination
378→    buildPagination(totalPages, page);
379→
380→  } catch (err) {
381→    loading.textContent = 'Error loading data: ' + err.message;
382→  }
383→}
