385→function buildPagination(totalPages, currentPage) {
386→  const container = document.getElementById('pagination');
387→  let html = '';
388→
389→  html += `<button ${currentPage <= 1 ? 'disabled' : ''} onclick="goToPage(1)">First</button>`;
390→  html += `<button ${currentPage <= 1 ? 'disabled' : ''} onclick="goToPage(${currentPage - 1})">Prev</button>`;
391→
392→  // Page number buttons (show max 7)
393→  let start = Math.max(1, currentPage - 3);
394→  let end = Math.min(totalPages, start + 6);
395→  start = Math.max(1, end - 6);
396→
397→  for (let i = start; i <= end; i++) {
398→    html += `<button class="${i === currentPage ? 'active' : ''}" onclick="goToPage(${i})">${i}</button>`;
399→  }
400→
401→  html += `<button ${currentPage >= totalPages ? 'disabled' : ''} onclick="goToPage(${currentPage + 1})">Next</button>`;
402→  html += `<button ${currentPage >= totalPages ? 'disabled' : ''} onclick="goToPage(${totalPages})">Last</button>`;
403→
404→  html += ` <select onchange="changeLimit(this.value)">`;
405→  [25, 50, 100, 200].forEach(n => {
406→    html += `<option value="${n}" ${n === currentLimit ? 'selected' : ''}>${n} per page</option>`;
407→  });
408→  html += `</select>`;
409→
410→  container.innerHTML = html;
411→}
