440→function formatTimestamp(ts) {
441→  if (!ts) return '';
442→  try {
443→    const d = new Date(ts);
444→    if (isNaN(d.getTime())) return ts;
445→    return d.toISOString().replace('T', ' ').replace(/\.\d{3}Z$/, ' UTC');
