454→function filterTable() {
455→  const tbody = document.getElementById('tableBody');
456→  const filters = document.querySelectorAll('.filter-input');
457→  const rows = tbody.querySelectorAll('tr');
458→  rows.forEach(row => {
459→    let show = true;
460→    filters.forEach((filter, index) => {
461→      const val = filter.value.toLowerCase();
462→      if (val) {
463→        const cell = row.cells[index + 1]; // +1 for checkbox column
464→        if (cell) {
465→          if (!cell.textContent.toLowerCase().includes(val)) show = false;
466→        }
467→      }
468→    });
469→    row.style.display = show ? '' : 'none';
470→  });
