480→async function deleteSelected() {
481→  const checked = document.querySelectorAll('.row-cb:checked');
482→  if (checked.length === 0) return;
483→  if (!confirm(`Delete ${checked.length} selected row(s)?`)) return;
484→
485→  const ids = Array.from(checked).map(cb => cb.value).join(',');
486→  let url = `/api/admin/mcp/delete?table=${currentTable}&ids=${encodeURIComponent(ids)}`;
487→  if (PASSWORD) url += '&password=' + encodeURIComponent(PASSWORD);
488→
489→  try {
490→    const resp = await fetch(url, { method: 'DELETE' });
491→    if (!resp.ok) throw new Error('HTTP ' + resp.status);
492→    const json = await resp.json();
493→    alert(`Deleted ${json.deleted} row(s)`);
494→    fetchData();
495→  } catch (err) {
