500→async function deleteAll() {
501→  const scope = currentSearch ? 'all filtered rows' : 'ALL rows';
502→  if (!confirm(`Delete ${scope} from ${currentTable}? This cannot be undone.`)) return;
503→
504→  let url = `/api/admin/mcp/delete?table=${currentTable}&all=true`;
505→  if (PASSWORD) url += '&password=' + encodeURIComponent(PASSWORD);
506→  if (currentSearch) url += '&search=' + encodeURIComponent(currentSearch);
507→
508→  try {
509→    const resp = await fetch(url, { method: 'DELETE' });
510→    if (!resp.ok) throw new Error('HTTP ' + resp.status);
511→    const json = await resp.json();
512→    alert(`Deleted ${json.deleted} row(s)`);
513→    fetchData();
514→  } catch (err) {
515→    alert('Delete failed: ' + err.message);
516→  }
