519→let columnWidths = {}; // Persist widths across re-renders, keyed by column index
520→let resizing = false; // Suppress sort click after drag
521→
522→function initColumnResize() {
523→  const table = document.getElementById('dataTable');
524→  if (!table) return;
525→  const headerRow = table.querySelector('thead tr:first-child');
526→  if (!headerRow) return;
527→  const ths = headerRow.querySelectorAll('th');
528→
529→  // Restore saved widths or capture initial computed widths
530→  ths.forEach((th, i) => {
531→    if (columnWidths[i]) {
532→      th.style.width = columnWidths[i];
533→    } else {
534→      th.style.width = th.offsetWidth + 'px';
535→    }
536→  });
537→
538→  document.querySelectorAll('.resize-handle').forEach(handle => {
539→    handle.addEventListener('mousedown', function(e) {
540→      e.preventDefault();
541→      e.stopPropagation();
542→      resizing = true;
543→      const th = this.parentElement;
544→      const colIndex = Array.from(th.parentElement.children).indexOf(th);
545→      const startX = e.pageX;
546→      const startWidth = th.offsetWidth;
547→      this.classList.add('active');
548→
549→      const onMouseMove = (e) => {
550→        const newWidth = Math.max(40, startWidth + (e.pageX - startX));
551→        th.style.width = newWidth + 'px';
552→        columnWidths[colIndex] = newWidth + 'px';
553→      };
554→      const onMouseUp = () => {
555→        this.classList.remove('active');
556→        document.removeEventListener('mousemove', onMouseMove);
557→        document.removeEventListener('mouseup', onMouseUp);
558→        // Delay resetting flag so the click event on th is suppressed
559→        setTimeout(() => { resizing = false; }, 50);
560→      };
561→      document.addEventListener('mousemove', onMouseMove);
562→      document.addEventListener('mouseup', onMouseUp);
563→    });
564→  });
565→}
566→
567→// Init
568→document.addEventListener('DOMContentLoaded', () => {
569→  buildAdminTabs();
570→  fetchData();
571→});
572→
573→// Keyboard shortcut: Escape closes modal
574→document.addEventListener('keydown', e => {
575→  if (e.key === 'Escape') closeModal();
576→});
577→</script>
578→</body>
579→</html>
