function exportCSV() {
  let url = '/api/admin/realtime/export';
  url += PASSWORD ? '?password=' + encodeURIComponent(PASSWORD) : '';
  if (currentSearch) url += (PASSWORD ? '&' : '?') + 'search=' + encodeURIComponent(currentSearch);
