  const ids = Array.from(checked).map(cb => cb.value).join(',');
  let url = `/api/admin/realtime/delete?ids=${encodeURIComponent(ids)}`;
  if (PASSWORD) url += '&password=' + encodeURIComponent(PASSWORD);

  try {
