		}
		if req.Password != *adminPassword {
			http.Error(w, "Unauthorized", http.StatusUnauthorized)
			return
		}
	}

	// Validate trackID
	if req.TrackID == "" {
		http.Error(w, "trackID is required", http.StatusBadRequest)
		return
	}

